Add-Type -AssemblyName System.Windows.Forms
Add-Type -AssemblyName System.Drawing

$form = New-Object System.Windows.Forms.Form
$form.Text = 'Print Driver Installer'
$form.Size = New-Object System.Drawing.Size(300,300)
$form.StartPosition = 'CenterScreen'
$iconBase64      = ''
$iconBytes       = [Convert]::FromBase64String($iconBase64)
$stream          = New-Object IO.MemoryStream($iconBytes, 0, $iconBytes.Length)
$stream.Write($iconBytes, 0, $iconBytes.Length);
$iconImage       = [System.Drawing.Image]::FromStream($stream, $true)
$Form.Icon       = [System.Drawing.Icon]::FromHandle((New-Object System.Drawing.Bitmap -Argument $stream).GetHIcon())

$OKButton = New-Object System.Windows.Forms.Button
$OKButton.Location = New-Object System.Drawing.Point(75,210)
$OKButton.Size = New-Object System.Drawing.Size(75,23)
$OKButton.Text = 'OK'
$OKButton.DialogResult = [System.Windows.Forms.DialogResult]::OK
$OKButton.Enabled = $False
$form.AcceptButton = $OKButton
$form.Controls.Add($OKButton)


$CancelButton = New-Object System.Windows.Forms.Button
$CancelButton.Location = New-Object System.Drawing.Point(150,210)
$CancelButton.Size = New-Object System.Drawing.Size(75,23)
$CancelButton.Text = 'Cancel'
$CancelButton.DialogResult = [System.Windows.Forms.DialogResult]::Cancel
$form.CancelButton = $CancelButton
$form.Controls.Add($CancelButton)

$label = New-Object System.Windows.Forms.Label
$label.Location = New-Object System.Drawing.Point(10,20)
$label.Size = New-Object System.Drawing.Size(280,20)
$label.Text = 'Please select your printer model:'
$form.Controls.Add($label)

$listBox = New-Object System.Windows.Forms.ListBox
$listBox.Location = New-Object System.Drawing.Point(10,40)
$listBox.Size = New-Object System.Drawing.Size(260,20)
$listBox.Height = 150
$listBox.add_SelectedIndexChanged({$OKButton.Enabled = $true})


[void] $listBox.Items.Add('DCP-7060D')
[void] $listBox.Items.Add('HL-1110')
[void] $listBox.Items.Add('HL-2130')
[void] $listBox.Items.Add('HL-2132')
[void] $listBox.Items.Add('HL-2140')
[void] $listBox.Items.Add('HL-L2300')
[void] $listBox.Items.Add('HL-L2340DW')
[void] $listBox.Items.Add('HL-L2365DW')
[void] $listBox.Items.Add('MFC-L2700DW')
[void] $listBox.Items.Add('MFC-L2710DW')



$form.Controls.Add($listBox)

$result = $form.ShowDialog()

if ($result -eq [System.Windows.Forms.DialogResult]::OK) {

$x = $listBox.SelectedItem.ToString()

$wshell = New-Object -ComObject Wscript.Shell
$success = $wshell.Popup("Printer has been installed successfully!",0,"Done")

$DCP7060D = "\\hopecc.sa.edu.au\source\SCCM\Applications\Printer Drivers\DCP-7060D\dpinst.exe"
$HL1110 = "\\hopecc.sa.edu.au\source\SCCM\Applications\Printer Drivers\HL-1110\dpinstx64.exe"
$HL2130 = "\\hopecc.sa.edu.au\source\SCCM\Applications\Printer Drivers\HL-2130\dpinst.exe"
$HL2132 = "\\hopecc.sa.edu.au\source\SCCM\Applications\Printer Drivers\HL-2132\dpinst.exe"
$HLL2300D = "\\hopecc.sa.edu.au\source\SCCM\Applications\Printer Drivers\HL-L2300D\dpinstx64.exe"
$HLL2340DW = "\\hopecc.sa.edu.au\source\SCCM\Applications\Printer Drivers\HL-L2340DW\dpinstx64.exe"
$HLL2365DW = "\\hopecc.sa.edu.au\source\SCCM\Applications\Printer Drivers\HL-L2340DW\dpinstx64.exe"
$MFCL2700DW = "\\hopecc.sa.edu.au\source\SCCM\Applications\Printer Drivers\MFC-L2700DW\dpinstx64.exe"
$MFCL2710DW = "\\hopecc.sa.edu.au\source\SCCM\Applications\Printer Drivers\MFC-L2710DW\dpinstx64.exe"


if ($x -eq "DCP-7060D") 

{ Start-Process $DCP7060D 
  Start-Sleep 5
    $success
 }

elseif ($x -eq "HL-1110") 

{ Start-Process $HL1110 
  Start-Sleep 5
    $success
 }

 elseif ($x -eq "HL-2130") 

{ Start-Process $HL2130 
  Start-Sleep 5
    $success
 }

elseif ($x -eq "HL-2132") 

{ Start-Process $HL2132 
  Start-Sleep 5
    $success
 }

elseif ($x -eq "HL-2140") 

{ PNPUtil.exe /add-driver "\\hopecc.sa.edu.au\source\SCCM\Applications\Printer Drivers\HL-2140\BROHLA7A.INF" /install 
  Start-Sleep 5
    $success
 }

elseif ($x -eq "HL-L2300") 

{ Start-Process $HLL2300 
  Start-Sleep 5
    $success
 }

elseif ($x -eq "HL-L2340DW") 

{ Start-Process $HLL2340DW 
  Start-Sleep 5
    $success
 }

elseif ($x -eq "HL-L2365DW") 

{ Start-Process $HLL2365DW 
  Start-Sleep 5
    $success
 }

elseif ($x -eq "MFC-L2700DW") 

{ Start-Process $MFCL2700DW 
  Start-Sleep 5
    $success
 }

elseif ($x -eq "MFC-L2710DW") 

{ Start-Process $MFCL2710DW 
  Start-Sleep 5
    $success
 } 
 
 }



